// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public {
        c = new airdrop();
    }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        // Widen the domain: only need a non-empty destination array, and use a
        // recording callee that implements the exact transferFrom selector.
        if (tos.length == 0) return;

        Recorder rec = new Recorder();
        bool ok = c.transfer(from, address(rec), tos, v);
        assertTrue(ok);

        // Reference calls transferFrom for every destination, including index 0.
        // Mutant starts at index 1, so index 0 produces no recorded call.
        bool sentFirst = rec.sent(from, tos[0], v);
        assertTrue(sentFirst);
    }
}

contract Recorder {
    mapping(address => mapping(address => mapping(uint256 => uint256))) public count;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        count[from][to][amount] += 1;
        return true;
    }

    function sent(address from, address to, uint256 amount) external view returns (bool) {
        return count[from][to][amount] > 0;
    }
}
